/**
 * Makes the princess models generated by TRELLIS.2 ready for the game.
 *
 *   npm i --no-save @gltf-transform/core@4.1.1 @gltf-transform/extensions@4.1.1 \
 *     @gltf-transform/functions@4.1.1 meshoptimizer@0.22.0      (once)
 *   node art-source/princess/trellis/prepare.mjs
 *
 * TRELLIS.2 (huggingface.co/spaces/microsoft/TRELLIS.2) turns one picture into one textured
 * model. Its files are saved in art-source/princess/trellis/raw/ under the names in PIECES below
 * (what each one is and how it stands), and this writes them to public/models/princess-trellis/:
 *
 *   - painted, not metal: TRELLIS marks the whole model as metal, which under the game's lights
 *     (nothing to reflect) came out dark brown;
 *   - standing on the floor (y = 0), its middle on x = 0 and z = 0, as tall as PIECES says, in
 *     metres, facing +z, its root named <row>_<id> as the other characters' pieces;
 *   - lighter: fewer triangles where they do not change the shape (95 000 → about 40 000),
 *     positions and normals stored small and the whole compressed with meshopt (the game's
 *     loader, drei's useGLTF, reads it without anything else), the texture kept as it came
 *     (1024, webp);
 *   - checked: the validator report and the sizes go to docs/princess-trellis-validation.json.
 *
 * src/characters/princess/trellis-library.json lists what was made, for Princess3D.
 */
import fs from 'node:fs/promises';
import path from 'node:path';
import { NodeIO } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import { dedup, getBounds, meshopt, prune, quantize, simplify, weld } from '@gltf-transform/functions';
import { MeshoptEncoder, MeshoptSimplifier } from 'meshoptimizer';
import validator from 'gltf-validator';

const HERE = path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Z]:)/, '$1'));
const ROOT = path.join(HERE, '..', '..', '..');
const RAW = path.join(HERE, 'raw');
const OUT = path.join(ROOT, 'public', 'models', 'princess-trellis');
const LIB = path.join(ROOT, 'src', 'characters', 'princess', 'trellis-library.json');
const REPORT = path.join(ROOT, 'docs', 'princess-trellis-validation.json');

/**
 * Every model: its file in raw/, what it is (a whole princess, or one piece: dress, hair, head)
 * and how tall it stands in the game (metres; the game's princess is about 3.6 m tall, as the
 * flat one fills her 1024 × 1536 sheet at 2.5 mm a pixel).
 */
const PIECES = [
  { file: 'princesa-azul.glb', row: 'whole', id: 'star-bun-sleepy-tongue', height: 3.6 },
];

const TRIANGLES = 40000;

await MeshoptEncoder.ready;
await MeshoptSimplifier.ready;
await fs.mkdir(OUT, { recursive: true });
const io = new NodeIO().registerExtensions(ALL_EXTENSIONS).registerDependencies({ 'meshopt.encoder': MeshoptEncoder });

let library = { pieces: {} };
try {
  library = JSON.parse(await fs.readFile(LIB, 'utf8'));
} catch {}
const reports = [];

for (const piece of PIECES) {
  const src = path.join(RAW, piece.file);
  try {
    await fs.access(src);
  } catch {
    console.log('missing', piece.file, '(skipped)');
    continue;
  }
  const doc = await io.read(src);
  const scene = doc.getRoot().getDefaultScene() ?? doc.getRoot().listScenes()[0];

  // painted, not metal
  for (const m of doc.getRoot().listMaterials()) {
    m.setMetallicFactor(0);
    m.setRoughnessFactor(0.55);
    const t = m.getMetallicRoughnessTexture();
    m.setMetallicRoughnessTexture(null);
    if (t && !t.listParents().some((p) => p !== doc.getRoot())) t.dispose();
    m.setName(piece.row === 'whole' ? 'Princess' : `${piece.row}_${piece.id}`);
  }

  // fewer triangles, then small and compressed
  await doc.transform(weld(), simplify({ simplifier: MeshoptSimplifier, ratio: 1, error: 0.0005, lockBorder: false }));
  let tris = 0;
  for (const mesh of doc.getRoot().listMeshes()) for (const p of mesh.listPrimitives()) tris += (p.getIndices()?.getCount() ?? 0) / 3;
  if (tris > TRIANGLES) await doc.transform(simplify({ simplifier: MeshoptSimplifier, ratio: TRIANGLES / tris, error: 0.01 }));

  // standing on the floor, in the middle, as tall as it should be: one root node holds the
  // models' own nodes, moved and scaled
  const b = getBounds(scene);
  const size = b.max[1] - b.min[1];
  const k = piece.height / size;
  const root = doc.createNode(`${piece.row}_${piece.id}`)
    .setScale([k, k, k])
    .setTranslation([-((b.min[0] + b.max[0]) / 2) * k, -b.min[1] * k, -((b.min[2] + b.max[2]) / 2) * k]);
  for (const n of scene.listChildren()) {
    scene.removeChild(n);
    root.addChild(n);
  }
  scene.addChild(root);

  await doc.transform(dedup(), prune(), quantize(), meshopt({ encoder: MeshoptEncoder, level: 'medium' }));

  const name = `${piece.row}-${piece.id}.glb`;
  const bytes = await io.writeBinary(doc);
  await fs.writeFile(path.join(OUT, name), bytes);
  const v = await validator.validateBytes(new Uint8Array(bytes), { maxIssues: 20 });
  let after = 0;
  for (const mesh of doc.getRoot().listMeshes()) for (const p of mesh.listPrimitives()) after += (p.getIndices()?.getCount() ?? 0) / 3;
  const report = { piece: name, bytes: bytes.byteLength, triangles: Math.round(after), errors: v.issues.numErrors, warnings: v.issues.numWarnings };
  reports.push(report);
  if (v.issues.numErrors) console.log(JSON.stringify(v.issues.messages.slice(0, 5), null, 1));
  library.pieces[`${piece.row}:${piece.id}`] = { url: `models/princess-trellis/${name}`, group: `${piece.row}_${piece.id}`, height: piece.height };
  console.log(name.padEnd(40), String(bytes.byteLength).padStart(9), 'bytes', String(Math.round(after)).padStart(7), 'triangles', v.issues.numErrors, 'errors', v.issues.numWarnings, 'warnings');
}

await fs.writeFile(LIB, JSON.stringify(library, null, 2));
await fs.writeFile(REPORT, JSON.stringify(reports, null, 2));
